export function SourceLibrary({ connections, disconnecting, onConnect, onDisconnect }: { connections: ConnectionStatus[]; disconnecting: ConnectionStatus['provider'] | null; onConnect: (provider: ConnectionStatus['provider']) => Promise<void>; onDisconnect: (provider: ConnectionStatus['provider']) => void }) {
  const connectedCount = connections.filter((item) => item.connected).length;
  return <FlatList data={providers} keyExtractor={(item) => item.id} contentContainerStyle={styles.sourcesList} ListHeaderComponent={<View style={styles.sourcesHeader}><Text style={styles.overline}>YOUR PRIVATE LIBRARY</Text><Text style={styles.sourcesTitle}>Nguồn dữ liệu</Text><Text style={styles.sourcesCopy}>Kết nối một lần, Mondaiy chỉ đọc những nguồn bạn cho phép.</Text><View style={styles.sourcesMetric}><View style={styles.metricIcon}><Ionicons name="shield-checkmark" size={20} color="#204D49" /></View><View><Text style={styles.metricValue}>{connectedCount} nguồn đang kết nối</Text><Text style={styles.metricNote}>Bạn có thể ngắt bất kỳ lúc nào</Text></View></View></View>} renderItem={({ item }) => {
    const state = connections.find((connection) => connection.provider === item.id);
    const connected = Boolean(state?.connected);
    const busy = disconnecting === item.id;
    return <View style={styles.sourceCard}><View style={[styles.sourceIcon, { backgroundColor: `${item.color}18` }]}><Ionicons name={item.icon} size={23} color={item.color} /></View><View style={styles.sourceBody}><View style={styles.sourceTop}><View><Text style={styles.sourceTitle}>{item.title}</Text><Text style={styles.sourceDetail}>{connected ? state?.accountLabel || 'Đã cấp quyền truy cập' : item.detail}</Text></View><View style={[styles.sourceStatus, connected ? styles.sourceStatusOn : styles.sourceStatusOff]}><View style={[styles.sourceDot, connected && styles.sourceDotOn]} /><Text style={[styles.sourceStatusText, connected && styles.sourceStatusTextOn]}>{connected ? 'Đã kết nối' : 'Chưa kết nối'}</Text></View></View><Pressable accessibilityRole="button" disabled={busy} style={[styles.sourceAction, connected ? styles.sourceDisconnect : styles.sourceConnect, busy && styles.disabled]} onPress={() => connected ? onDisconnect(item.id) : void onConnect(item.id)}><Text style={[styles.sourceActionText, connected && styles.sourceDisconnectText]}>{busy ? 'Đang xử lý…' : connected ? 'Ngắt kết nối' : 'Kết nối'}</Text><Ionicons name={connected ? 'unlink-outline' : 'arrow-forward'} size={16} color={connected ? '#A4534E' : cream} /></Pressable></View></View>;
  }} />;
}

